const AiExtractSchema = z
  .object({
    prompt: z
      .string()
      .openapi({
        description:
          'The prompt provided to a Large Language Model (LLM) in the request. The prompt can be up to 10000 characters long and it can be an XML or a JSON schema.',
        example:
          '\\"fields\\":[{\\"type\\":\\"string\\",\\"key\\":\\"name\\",\\"displayName\\":\\"Name\\",\\"description\\":\\"The customer name\\",\\"prompt\\":\\"Name is always the first word in the document\\"},{\\"type\\":\\"date\\",\\"key\\":\\"last_contacted_at\\",\\"displayName\\":\\"Last Contacted At\\",\\"description\\":\\"When this customer was last contacted at\\"}]',
      }),
    items: z
      .array(AiItemBaseSchema)
      .min(1)
      .max(25)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description: 'The items that LLM will process. Currently, you can use files only.',
      }),
    ai_agent: AiExtractAgentSchema.and(
      z.any().openapi({ description: 'The AI agent to be used for the extraction.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'AI metadata freeform extraction request object.',
    required: ['prompt', 'items'],
    title: 'AI metadata freeform extraction request',
    'x-box-tag': 'ai',
  })
  .openapi('AiExtract')

