const AiTextGenSchema = z
  .object({
    prompt: z
      .string()
      .openapi({
        description:
          "The prompt provided by the client to be answered by the LLM. The prompt's length is limited to 10000 characters.",
        example: 'Write an email to a client about the importance of public APIs.',
      }),
    items: z
      .array(
        z
          .object({
            id: z.string().openapi({ description: 'The ID of the item.', example: '123' }),
            type: z
              .literal('file')
              .openapi({ description: 'The type of the item.', example: 'file' }),
            content: z
              .string()
              .exactOptional()
              .openapi({
                description:
                  'The content to use as context for generating new text or editing existing text.',
                example: 'This is file content that is relevant to the text gen request.',
              }),
          })
          .openapi({
            required: ['id', 'type'],
            description: 'The item to be processed by the LLM.',
          }),
      )
      .length(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description:
          'The items to be processed by the LLM, often files.\nThe array can include **exactly one** element.\n\n**Note**: Box AI handles documents with text representations up to 2MB in size.\nIf the file size exceeds 2MB, the first 2MB of text representation will be processed.',
      }),
    dialogue_history: z
      .array(AiDialogueHistorySchema)
      .exactOptional()
      .openapi({
        description:
          'The history of prompts and answers previously passed to the LLM. This parameter provides the additional context to the LLM when generating the response.',
      }),
    ai_agent: AiTextGenAgentSchema.and(
      z.any().openapi({ description: 'The AI agent to be used for generating text.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'AI text gen request object.',
    required: ['prompt', 'items'],
    title: 'AI text gen request',
    'x-box-tag': 'ai',
  })
  .openapi('AiTextGen')

