export const putFilesUploadSessionsUploadSessionIdRoute = createRoute({
  method: 'put',
  path: '/files/upload_sessions/{upload_session_id}',
  tags: ['Uploads (Chunked)'],
  summary: 'Upload part of file',
  description:
    'Uploads a chunk of a file for an upload session.\n\nThe actual endpoint URL is returned by the [`Create upload session`](https://developer.box.com/reference/post-files-upload-sessions)\nand [`Get upload session`](https://developer.box.com/reference/get-files-upload-sessions-id) endpoints.',
  operationId: 'put_files_upload_sessions_id',
  request: {
    params: z.object({
      upload_session_id: z
        .string()
        .openapi({
          param: {
            name: 'upload_session_id',
            in: 'path',
            description: 'The ID of the upload session.',
            required: true,
            schema: { type: 'string' },
            example: 'D5E3F7A',
          },
        }),
    }),
    headers: z.object({
      digest: z
        .string()
        .openapi({
          param: {
            name: 'digest',
            in: 'header',
            description:
              'The [RFC3230][1] message digest of the chunk uploaded.\n\n`SHA-1` and `SHA-512` ([RFC5843][2]) are supported. The digest must be base64\nencoded. The format of this header is as\n`sha=BASE64_ENCODED_DIGEST` for `SHA-1`, or\n`sha-512=BASE64_ENCODED_DIGEST` for `SHA-512`.\n\nTo get the value for the digest, use the\nopenSSL command to encode the file part:\n`openssl sha1 -binary <FILE_PART_NAME> | base64` for `SHA-1`, or\n`openssl sha512 -binary <FILE_PART_NAME> | base64` for `SHA-512`.\n\n[1]: https://tools.ietf.org/html/rfc3230\n[2]: https://tools.ietf.org/html/rfc5843',
            required: true,
            schema: { type: 'string' },
            example: 'sha=fpRyg5eVQletdZqEKaFlqwBXJzM=',
          },
        }),
      'content-range': z
        .string()
        .openapi({
          param: {
            name: 'content-range',
            in: 'header',
            description:
              "The byte range of the chunk.\n\nMust not overlap with the range of a part already\nuploaded this session. Each part’s size must be\nexactly equal in size to the part size specified\nin the upload session that you created.\nOne exception is the last part of the file, as this can be smaller.\n\nWhen providing the value for `content-range`, remember that:\n\n* The lower bound of each part's byte range\n  must be a multiple of the part size.\n* The higher bound must be a multiple of the part size - 1.",
            required: true,
            schema: { type: 'string' },
            example: 'bytes 8388608-16777215/445856194',
          },
        }),
    }),
    body: {
      content: {
        'application/octet-stream': {
          schema: z
            .file()
            .openapi({
              type: 'string',
              format: 'binary',
              description: 'The binary content of the file.',
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description:
        'Chunk has been uploaded successfully.\n\nThe response always includes `sha512`. It also includes\n`sha1` if the `Digest` header used `SHA-1`.',
      content: { 'application/json': { schema: UploadedPartSchema } },
    },
    409: {
      description:
        'Returns an error if the chunk conflicts with another\nchunk previously uploaded.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    412: {
      description: 'Returns an error if a precondition was not met.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    416: {
      description:
        'Returns an error if the content range does not match a specified range\nfor the session.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
  servers: [
    {
      url: 'https://{box-upload-server}/api/2.0',
      description: 'Server for file uploads.',
      variables: {
        'box-upload-server': {
          description: 'The server for the upload session.',
          default: 'upload.box.com',
        },
      },
    },
  ],
})

