export const getFilesUploadSessionsUploadSessionIdPartsRoute = createRoute({
  method: 'get',
  path: '/files/upload_sessions/{upload_session_id}/parts',
  tags: ['Uploads (Chunked)'],
  summary: 'List parts',
  description:
    'Return a list of the chunks uploaded to the upload session so far.\n\nThe actual endpoint URL is returned by the [`Create upload session`](https://developer.box.com/reference/post-files-upload-sessions)\nand [`Get upload session`](https://developer.box.com/reference/get-files-upload-sessions-id) endpoints.',
  operationId: 'get_files_upload_sessions_id_parts',
  request: {
    params: z.object({
      upload_session_id: z
        .string()
        .openapi({
          param: {
            name: 'upload_session_id',
            in: 'path',
            description: 'The ID of the upload session.',
            required: true,
            schema: { type: 'string' },
            example: 'D5E3F7A',
          },
        }),
    }),
    query: z.object({
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description:
              'The offset of the item at which to begin the response.\n\nQueries with offset parameter value\nexceeding 10000 will be rejected\nwith a 400 response.',
            required: false,
            schema: { type: 'integer', format: 'int64', default: 0 },
            example: 1000,
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'The maximum number of items to return per page.',
            required: false,
            schema: { type: 'integer', format: 'int64', maximum: 1000 },
            example: 1000,
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        "Returns a list of parts that have been uploaded.\n\nEach part includes the hash type used to upload it. Parts\nuploaded with a `SHA-512` `Digest` header don't include `sha1`.",
      content: { 'application/json': { schema: UploadPartsSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
  servers: [
    {
      url: 'https://{box-upload-server}/api/2.0',
      description: 'Server for file uploads.',
      variables: {
        'box-upload-server': {
          description: 'The server for the upload session.',
          default: 'upload.box.com',
        },
      },
    },
  ],
})

export const postFilesUploadSessionsUploadSessionIdPlanRoute = createRoute({
  method: 'post',
  path: '/files/upload_sessions/{upload_session_id}/plan',
  tags: ['Uploads (Chunked)'],
  summary: 'Plan upload session',
  description:
    'Plan an upload session by checking which parts already exist on the server.\nThis endpoint allows clients to optimize uploads by skipping parts that\nhave already been uploaded (cache hits) and only uploading missing parts.\n\nThe actual endpoint URL is returned by the [`Create upload session`](https://developer.box.com/reference/post-files-upload-sessions)\nand [`Get upload session`](https://developer.box.com/reference/get-files-upload-sessions-id) endpoints.',
  operationId: 'post_files_upload_sessions_id_plan',
  request: {
    params: z.object({
      upload_session_id: z
        .string()
        .openapi({
          param: {
            name: 'upload_session_id',
            in: 'path',
            description: 'The ID of the upload session.',
            required: true,
            schema: { type: 'string' },
            example: 'D5E3F7A',
          },
        }),
    }),
    body: { content: { 'application/json': { schema: UploadSessionPlanRequestSchema } } },
  },
  responses: {
    200: {
      description:
        'Returns information about which parts already exist (hits)\nand which parts need to be uploaded (misses).',
      content: { 'application/json': { schema: UploadSessionPlanResponseSchema } },
    },
    404: {
      description: 'Returns an error if the upload session cannot be found.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
  servers: [
    {
      url: 'https://{box-upload-server}/api/2.0',
      description: 'Server for file uploads.',
      variables: {
        'box-upload-server': {
          description: 'The server for the upload session.',
          default: 'upload.box.com',
        },
      },
    },
  ],
})

export const postFilesUploadSessionsUploadSessionIdCommitRoute = createRoute({
  method: 'post',
  path: '/files/upload_sessions/{upload_session_id}/commit',
  tags: ['Uploads (Chunked)'],
  summary: 'Commit upload session',
  description:
    'Close an upload session and create a file from the uploaded chunks.\n\nThe actual endpoint URL is returned by the [`Create upload session`](https://developer.box.com/reference/post-files-upload-sessions)\nand [`Get upload session`](https://developer.box.com/reference/get-files-upload-sessions-id) endpoints.',
  operationId: 'post_files_upload_sessions_id_commit',
  request: {
    params: z.object({
      upload_session_id: z
        .string()
        .openapi({
          param: {
            name: 'upload_session_id',
            in: 'path',
            description: 'The ID of the upload session.',
            required: true,
            schema: { type: 'string' },
            example: 'D5E3F7A',
          },
        }),
    }),
    headers: z.object({
      digest: z
        .string()
        .openapi({
          param: {
            name: 'digest',
            in: 'header',
            description:
              'The [RFC3230][1] message digest of the whole file.\n\nOnly SHA1 is supported. The SHA1 digest must be Base64\nencoded. The format of this header is as\n`sha=BASE64_ENCODED_DIGEST`.\n\n`SHA-512` is not supported for the whole-file digest, even if\nthe parts were uploaded with `SHA-512` digests.\n\n[1]: https://tools.ietf.org/html/rfc3230',
            required: true,
            schema: { type: 'string' },
            example: 'sha=fpRyg5eVQletdZqEKaFlqwBXJzM=',
          },
        }),
      'if-match': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'if-match',
            in: 'header',
            description:
              "Ensures this item hasn't recently changed before\nmaking changes.\n\nPass in the item's last observed `etag` value\ninto this header and the endpoint will fail\nwith a `412 Precondition Failed` if it\nhas changed since.",
            required: false,
            schema: { type: 'string' },
            example: '1',
          },
        }),
      'if-none-match': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'if-none-match',
            in: 'header',
            description:
              "Ensures an item is only returned if it has changed.\n\nPass in the item's last observed `etag` value\ninto this header and the endpoint will fail\nwith a `304 Not Modified` if the item has not\nchanged since.",
            required: false,
            schema: { type: 'string' },
            example: '1',
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              parts: z
                .array(UploadPartSchema)
                .openapi({
                  description:
                    'The list details for the uploaded parts.\n\nEach entry can include `sha1` or `sha512`. Include `sha512`\non every entry or on none of them. A request where only\nsome entries include `sha512` is rejected.\n\nInclude parts that the server already has, returned as\n`hits` by the [`Plan upload session`](https://developer.box.com/reference/post-files-upload-sessions-id-plan)\nendpoint. Use the `part_id`, `offset`, and `size` from the\nplan response. If the other entries include `sha512`,\ninclude the `sha512` value from the plan response.\nOtherwise, leave the hash out of these entries.',
                }),
            })
            .openapi({ required: ['parts'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns the file object in a list.',
      content: { 'application/json': { schema: FilesSchema } },
    },
    202: {
      description:
        'Returns when all chunks have been uploaded but not yet processed.\n\nInspect the upload session to get more information about the\nprogress of processing the chunks, then retry committing the file\nwhen all chunks have processed.',
      headers: z.object({
        'Retry-After': {
          description:
            'Indicates the number of seconds the client should wait before\nattempting their commit request again.',
          schema: z
            .int()
            .exactOptional()
            .openapi({
              description:
                'Indicates the number of seconds the client should wait before\nattempting their commit request again.',
              param: { required: false },
            }),
        },
      }),
    },
    400: {
      description:
        'Returns an error if the request body is not valid.\n\n* `invalid_parts_field` - Only some entries in `parts` include\n  `sha512`. Include `sha512` on every entry or on none of them.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    409: {
      description:
        'Returns an error if there is already a file with the same name\nin the target folder.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    412: {
      description: 'Returns an error if the `If-Match` or `If-None-Match` conditions fail.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
  servers: [
    {
      url: 'https://{box-upload-server}/api/2.0',
      description: 'Server for file uploads.',
      variables: {
        'box-upload-server': {
          description: 'The server for the upload session.',
          default: 'upload.box.com',
        },
      },
    },
  ],
})

export const postFilesFileIdCopyRoute = createRoute({
  method: 'post',
  path: '/files/{file_id}/copy',
  tags: ['Files'],
  summary: 'Copy file',
  description: 'Creates a copy of a file.',
  operationId: 'post_files_id_copy',
  request: {
    params: z.object({
      file_id: z
        .string()
        .openapi({
          param: {
            name: 'file_id',
            in: 'path',
            description:
              'The unique identifier that represents a file.\n\nThe ID for any file can be determined\nby visiting a file in the web application\nand copying the ID from the URL. For example,\nfor the URL `https://*.app.box.com/files/123`\nthe `file_id` is `123`.',
            required: true,
            schema: { type: 'string' },
            example: '12345',
          },
        }),
    }),
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'fields',
            in: 'query',
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            required: false,
            schema: { type: 'array', items: { type: 'string' } },
            example: ['id', 'type', 'name'],
            explode: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .max(255)
                .exactOptional()
                .openapi({
                  description:
                    'An optional new name for the copied file.\n\nThere are some restrictions to the file name. Names containing\nnon-printable ASCII characters, forward and backward slashes\n(`/`, `\\`), and protected names like `.` and `..` are\nautomatically sanitized by removing the non-allowed\ncharacters.',
                  example: 'FileCopy.txt',
                }),
              version: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'An optional ID of the specific file version to copy.',
                  example: '0',
                }),
              parent: z
                .object({
                  id: z
                    .string()
                    .openapi({
                      description: 'The ID of folder to copy the file to.',
                      example: '0',
                    }),
                })
                .openapi({
                  description: 'The destination folder to copy the file to.',
                  required: ['id'],
                }),
            })
            .openapi({ required: ['parent'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description:
        'Returns a new file object representing the copied file.\n\nNot all available fields are returned by default. Use the\n[fields](#parameter-fields) query parameter to explicitly request\nany specific fields.',
      content: { 'application/json': { schema: FileFullSchema } },
    },
    304: {
      description:
        'Returns an empty response when the `If-None-Match` header matches\nthe current `etag` value of the file. This indicates that the file\nhas not changed since it was last requested.',
    },
    400: {
      description:
        'Returns an error if some of the parameters are missing or\nnot valid.\n\n* `bad_request` when a parameter is missing.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returns an error when the user does not have the\nright permissions to create the copy a file.\n\n* `forbidden_by_policy`: Returned if copying a file is\nforbidden due to information barrier restrictions.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description:
        'Returns an error if either the source file or the destination\nfolder could not be found, or the authenticated user does not\nhave access to either.\n\n* `not_found` when the authenticated user does not have access\n  to the source file or the destination folder.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    409: {
      description:
        '`operation_blocked_temporary`: Returned if either of the destination\nor source folders is locked due to another move, copy, delete or\nrestore operation in process.\n\nThe operation can be retried at a later point.\n\n`item_name_in_use` when a folder with the same name already\nexists.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

export const getFilesFileIdThumbnailExtensionRoute = createRoute({
  method: 'get',
  path: '/files/{file_id}/thumbnail.{extension}',
  tags: ['Files'],
  summary: 'Get file thumbnail',
  description:
    'Retrieves a thumbnail, or smaller image representation, of a file.\n\nSizes of `32x32`,`64x64`, `128x128`, and `256x256` can be returned in\nthe `.png` format and sizes of `32x32`, `160x160`, and `320x320`\ncan be returned in the `.jpg` format.\n\nThumbnails can be generated for the image and video file formats listed\n[found on our community site][1].\n\n[1]: https://community.box.com/t5/Migrating-and-Previewing-Content/File-Types-and-Fonts-Supported-in-Box-Content-Preview/ta-p/327',
  operationId: 'get_files_id_thumbnail_id',
  request: {
    params: z.object({
      file_id: z
        .string()
        .openapi({
          param: {
            name: 'file_id',
            in: 'path',
            description:
              'The unique identifier that represents a file.\n\nThe ID for any file can be determined\nby visiting a file in the web application\nand copying the ID from the URL. For example,\nfor the URL `https://*.app.box.com/files/123`\nthe `file_id` is `123`.',
            required: true,
            schema: { type: 'string' },
            example: '12345',
          },
        }),
      extension: z
        .enum(['png', 'jpg'])
        .openapi({
          param: {
            name: 'extension',
            in: 'path',
            description: 'The file format for the thumbnail.',
            required: true,
            schema: { type: 'string', enum: ['png', 'jpg'] },
            example: 'png',
          },
        }),
    }),
    query: z.object({
      min_height: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(32).max(320),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'min_height',
            in: 'query',
            description: 'The minimum height of the thumbnail.',
            schema: { type: 'integer', maximum: 320, minimum: 32 },
            example: 32,
            required: false,
          },
        }),
      min_width: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(32).max(320),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'min_width',
            in: 'query',
            description: 'The minimum width of the thumbnail.',
            schema: { type: 'integer', maximum: 320, minimum: 32 },
            example: 32,
            required: false,
          },
        }),
      max_height: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(32).max(320),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'max_height',
            in: 'query',
            description: 'The maximum height of the thumbnail.',
            required: false,
            schema: { type: 'integer', maximum: 320, minimum: 32 },
            example: 320,
          },
        }),
      max_width: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(32).max(320),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'max_width',
            in: 'query',
            description: 'The maximum width of the thumbnail.',
            required: false,
            schema: { type: 'integer', maximum: 320, minimum: 32 },
            example: 320,
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'When a thumbnail can be created the thumbnail data will be\nreturned in the body of the response.',
      content: {
        'image/jpg': {
          schema: z
            .file()
            .openapi({ type: 'string', format: 'binary', description: 'The thumbnail.' }),
        },
        'image/png': {
          schema: z
            .file()
            .openapi({ type: 'string', format: 'binary', description: 'The thumbnail.' }),
        },
      },
    },
    202: {
      description:
        'Sometimes generating a thumbnail can take a few seconds. In these\nsituations the API returns a `Location`-header pointing to a\nplaceholder graphic for this file type.\n\nThe placeholder graphic can be used in a user interface until the\nthumbnail generation has completed. The `Retry-After`-header indicates\nwhen to the thumbnail will be ready. At that time, retry this endpoint\nto retrieve the thumbnail.',
      headers: z.object({
        'Retry-After': {
          description:
            'The time in seconds after which the thumbnail will be available.\n\nYour application  only attempt to get the thumbnail again after\nthis time.',
          schema: z
            .preprocess(
              (val) =>
                typeof val === 'number' && Number.isSafeInteger(val)
                  ? BigInt(val)
                  : typeof val === 'string' && /^-?\d+$/.test(val)
                    ? BigInt(val)
                    : val,
              z.int64(),
            )
            .exactOptional()
            .openapi({
              description:
                'The time in seconds after which the thumbnail will be available.\n\nYour application  only attempt to get the thumbnail again after\nthis time.',
              param: { required: false },
              type: 'integer',
              format: 'int64',
            }),
        },
        Location: {
          description:
            'A pointer to a placeholder graphic that can be used until the\nthumbnail has been generated.',
          schema: z
            .url()
            .exactOptional()
            .openapi({
              description:
                'A pointer to a placeholder graphic that can be used until the\nthumbnail has been generated.',
              param: { required: false },
            }),
        },
      }),
    },
    302: {
      description:
        'Returns an error when Box is not able to create a thumbnail for this\nfile type.\n\nInstead, a `Location`-header pointing to a placeholder graphic for\nthis file type will be returned.',
      headers: z.object({
        Location: {
          description: 'A pointer to a placeholder graphic that can be used for this\nfile type.',
          schema: z
            .url()
            .exactOptional()
            .openapi({
              description:
                'A pointer to a placeholder graphic that can be used for this\nfile type.',
              param: { required: false },
            }),
        },
      }),
    },
    400: {
      description:
        'Returns an error if some of the parameters are missing or\nnot valid.\n\n* `requested_preview_unavailable` - an incorrect dimension was\n  requested. This will happen if the dimension requested is\n  larger or smaller than the available file sizes for the thumbnail\n  format, or when when any of the size constraints contradict\n  each other.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returned when the access token provided in the `Authorization` header\nis not recognized or not provided.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description:
        'Returned if the file is not found, or the user does not\nhave access to the file, or for additional reasons.\n\n* `preview_cannot_be_generated` - Box does not support thumbnails\n  for this type of file.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

export const getFilesFileIdCollaborationsRoute = createRoute({
  method: 'get',
  path: '/files/{file_id}/collaborations',
  tags: ['Collaborations (List)'],
  summary: 'List file collaborations',
  description:
    'Retrieves a list of pending and active collaborations for a\nfile. This returns all the users that have access to the file\nor have been invited to the file.',
  operationId: 'get_files_id_collaborations',
  request: {
    params: z.object({
      file_id: z
        .string()
        .openapi({
          param: {
            name: 'file_id',
            in: 'path',
            description:
              'The unique identifier that represents a file.\n\nThe ID for any file can be determined\nby visiting a file in the web application\nand copying the ID from the URL. For example,\nfor the URL `https://*.app.box.com/files/123`\nthe `file_id` is `123`.',
            required: true,
            schema: { type: 'string' },
            example: '12345',
          },
        }),
    }),
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'fields',
            in: 'query',
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            required: false,
            schema: { type: 'array', items: { type: 'string' } },
            example: ['id', 'type', 'name'],
            explode: false,
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'The maximum number of items to return per page.',
            required: false,
            schema: { type: 'integer', format: 'int64', maximum: 1000 },
            example: 1000,
          },
        }),
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'marker',
            in: 'query',
            description:
              'Defines the position marker at which to begin returning results. This is\nused when paginating using marker-based pagination.\n\nThis requires `usemarker` to be set to `true`.',
            required: false,
            schema: { type: 'string' },
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns a collection of collaboration objects. If there are no\ncollaborations on this file an empty collection will be returned.\n\nThis list includes pending collaborations, for which the `status`\nis set to `pending`, indicating invitations that have been sent but not\nyet accepted.',
      content: { 'application/json': { schema: CollaborationsSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

