export const getMetadataCascadePoliciesRoute = createRoute({
  method: 'get',
  path: '/metadata_cascade_policies',
  tags: ['Metadata cascade policies'],
  summary: 'List metadata cascade policies',
  description:
    'Retrieves a list of all the metadata cascade policies\nthat are applied to a given folder. This can not be used on the root\nfolder with ID `0`.',
  operationId: 'get_metadata_cascade_policies',
  request: {
    query: z.object({
      folder_id: z
        .string()
        .openapi({
          param: {
            name: 'folder_id',
            in: 'query',
            description:
              'Specifies which folder to return policies for. This can not be used on the\nroot folder with ID `0`.',
            required: true,
            schema: { type: 'string' },
            example: '31232',
          },
        }),
      owner_enterprise_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'owner_enterprise_id',
            in: 'query',
            description:
              'The ID of the enterprise ID for which to find metadata\ncascade policies. If not specified, it defaults to the\ncurrent enterprise.',
            schema: { type: 'string' },
            example: '31232',
            required: false,
          },
        }),
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'marker',
            in: 'query',
            description:
              'Defines the position marker at which to begin returning results. This is\nused when paginating using marker-based pagination.\n\nThis requires `usemarker` to be set to `true`.',
            required: false,
            schema: { type: 'string' },
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description:
              'The offset of the item at which to begin the response.\n\nQueries with offset parameter value\nexceeding 10000 will be rejected\nwith a 400 response.',
            required: false,
            schema: { type: 'integer', format: 'int64', default: 0 },
            example: 1000,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returns a list of metadata cascade policies.',
      content: { 'application/json': { schema: MetadataCascadePoliciesSchema } },
    },
    400: {
      description: 'Returns an error when any of the parameters are not in a valid format.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returns an error when the folder can not be accessed. This error often\nhappens when accessing the root folder with ID `0`.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description:
        'Returns an error when the folder can not be found or the user does not\nhave access to the folder.\n\n* `not_found` - The folder could not be found or the user does not have\n  access to the folder.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

export const postMetadataCascadePoliciesRoute = createRoute({
  method: 'post',
  path: '/metadata_cascade_policies',
  tags: ['Metadata cascade policies'],
  summary: 'Create metadata cascade policy',
  description:
    'Creates a new metadata cascade policy that applies a given\nmetadata template to a given folder and automatically\ncascades it down to any files within that folder.\n\nIn order for the policy to be applied a metadata instance must first\nbe applied to the folder the policy is to be applied to.',
  operationId: 'post_metadata_cascade_policies',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              folder_id: z
                .string()
                .openapi({
                  description:
                    'The ID of the folder to apply the policy to. This folder will\nneed to already have an instance of the targeted metadata\ntemplate applied to it.',
                  example: '1234567',
                }),
              scope: z
                .enum(['global', 'enterprise'])
                .openapi({
                  description:
                    'The scope of the targeted metadata template. This template will\nneed to already have an instance applied to the targeted folder.',
                  example: 'enterprise',
                }),
              templateKey: z
                .string()
                .openapi({
                  description:
                    "The key of the targeted metadata template. This template will\nneed to already have an instance applied to the targeted folder.\n\nIn many cases the template key is automatically derived\nof its display name, for example `Contract Template` would\nbecome `contractTemplate`. In some cases the creator of the\ntemplate will have provided its own template key.\n\nPlease [list the templates for an enterprise][list], or\nget all instances on a [file][file] or [folder][folder]\nto inspect a template's key.\n\n[list]: https://developer.box.com/reference/get-metadata-templates-enterprise\n[file]: https://developer.box.com/reference/get-files-id-metadata\n[folder]: https://developer.box.com/reference/get-folders-id-metadata",
                  example: 'productInfo',
                }),
            })
            .openapi({ required: ['folder_id', 'scope', 'templateKey'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns a new of metadata cascade policy.',
      content: { 'application/json': { schema: MetadataCascadePolicySchema } },
    },
    400: {
      description:
        'Returns an error when any of the parameters are not in a valid format.\n\n* `bad_request` - Either the `scope`, `templateKey`, or `folder_id` are\nnot in a valid format.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returns an error when trying to apply a policy to a restricted folder, for\nexample the root folder with ID `0`.\n\n* `forbidden` - Although the folder ID was valid and the user has access\nto the folder, the policy could not be applied to this folder.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description:
        'Returns an error when the template or folder can not be found, or when the\nuser does not have access to the folder or template.\n\n* `instance_tuple_not_found` - The template could not be found or the user\ndoes not have access to the template.\n* `not_found` - The folder could not be found or the user\ndoes not have access to the folder.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    409: {
      description:
        'Returns an error when a policy for this folder and template is already in\nplace.\n\n* `tuple_already_exists` - A cascade policy for this combination of\n`folder_id`, `scope` and `templateKey` already exists.',
      content: { 'application/json': { schema: ConflictErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

