export const putCollaborationsCollaborationIdRoute = createRoute({
  method: 'put',
  path: '/collaborations/{collaboration_id}',
  tags: ['Collaborations'],
  summary: 'Update collaboration',
  description:
    'Updates a collaboration.\nCan be used to change the owner of an item, or to\naccept collaboration invites. In case of accepting collaboration invite, role is not required.',
  operationId: 'put_collaborations_id',
  request: {
    params: z.object({
      collaboration_id: z
        .string()
        .openapi({
          param: {
            name: 'collaboration_id',
            in: 'path',
            description: 'The ID of the collaboration.',
            required: true,
            schema: { type: 'string' },
            example: '1234',
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              role: z
                .enum([
                  'editor',
                  'viewer',
                  'previewer',
                  'uploader',
                  'previewer uploader',
                  'viewer uploader',
                  'co-owner',
                  'owner',
                ])
                .exactOptional()
                .openapi({ description: 'The level of access granted.', example: 'editor' }),
              status: z
                .enum(['pending', 'accepted', 'rejected'])
                .exactOptional()
                .openapi({
                  description:
                    'Set the status of a `pending` collaboration invitation,\neffectively accepting, or rejecting the invite.',
                  example: 'accepted',
                }),
              expires_at: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    'Update the expiration date for the collaboration. At this date,\nthe collaboration will be automatically removed from the item.\n\nThis feature will only work if the **Automatically remove invited\ncollaborators: Allow folder owners to extend the expiry date**\nsetting has been enabled in the **Enterprise Settings**\nof the **Admin Console**. When the setting is not enabled,\ncollaborations can not have an expiry date and a value for this\nfield will be result in an error.\n\nAdditionally, a collaboration can only be given an\nexpiration if it was created after the **Automatically remove\ninvited collaborator** setting was enabled.',
                  example: '2019-08-29T23:59:00-07:00',
                }),
              can_view_path: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    "Determines if the invited users can see the entire parent path to\nthe associated folder. The user will not gain privileges in any\nparent folder and therefore can not see content the user is not\ncollaborated on.\n\nBe aware that this meaningfully increases the time required to load the\ninvitee's **All Files** page. We recommend you limit the number of\ncollaborations with `can_view_path` enabled to 1,000 per user.\n\nOnly an owner or co-owners can invite collaborators with a `can_view_path` of\n`true`. Only an owner can update `can_view_path` on existing collaborations.\n\n`can_view_path` can only be used for folder collaborations.\n\nWhen you delete a folder with `can_view_path=true`, collaborators may still see the parent path. \nFor instructions on how to remove this, see \n[Even though a folder invited via can_view_path is deleted, the path remains displayed](https://support.box.com/hc/en-us/articles/37472814319891-Even-though-a-folder-invited-via-can-view-path-is-deleted-the-path-remains-displayed).",
                  example: true,
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Returns an updated collaboration object unless the owner has changed.',
      content: { 'application/json': { schema: CollaborationSchema } },
    },
    204: {
      description:
        'If the role is changed to `owner`, the collaboration is deleted\nand a new collaboration is created. The previous `owner` of\nthe old collaboration will be a `co-owner` on the new collaboration.',
    },
    403: {
      description:
        'Returns an error if the authenticated user does not have the right\npermissions to update the collaboration.\n\nAdditionally, this error may occur when attempting to update the\n`expires_at` field for the collaboration without the **Automatically\nremove invited collaborators: Allow folder owners to extend the expiry\ndate** setting enabled in the admin dashboard of the enterprise.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

