export const getSharedItemsFoldersRoute = createRoute({
  method: 'get',
  path: '/shared_items#folders',
  tags: ['Shared links (Folders)'],
  summary: 'Find folder for shared link',
  description:
    'Return the folder represented by a shared link.\n\nA shared folder can be represented by a shared link,\nwhich can originate within the current enterprise or within another.\n\nThis endpoint allows an application to retrieve information about a\nshared folder when only given a shared link.',
  operationId: 'get_shared_items#folders',
  request: {
    headers: z.object({
      'if-none-match': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'if-none-match',
            in: 'header',
            description:
              "Ensures an item is only returned if it has changed.\n\nPass in the item's last observed `etag` value\ninto this header and the endpoint will fail\nwith a `304 Not Modified` if the item has not\nchanged since.",
            required: false,
            schema: { type: 'string' },
            example: '1',
          },
        }),
      boxapi: z
        .string()
        .openapi({
          param: {
            name: 'boxapi',
            in: 'header',
            description:
              'A header containing the shared link and optional password for the\nshared link.\n\nThe format for this header is as follows:\n\n`shared_link=[link]&shared_link_password=[password]`.',
            required: true,
            schema: { type: 'string' },
            example: 'shared_link=[link]&shared_link_password=[password]',
          },
        }),
    }),
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'fields',
            in: 'query',
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            required: false,
            schema: { type: 'array', items: { type: 'string' } },
            example: ['id', 'type', 'name'],
            explode: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns a full folder resource if the shared link is valid and\nthe user has access to it.',
      content: { 'application/json': { schema: FolderFullSchema } },
    },
    304: {
      description:
        'Returns an empty response when the `If-None-Match` header matches\nthe current `etag` value of the folder. This indicates that the folder\nhas not changed since it was last requested.',
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

