export const postWebLinksWebLinkIdRoute = createRoute({
  method: 'post',
  path: '/web_links/{web_link_id}',
  tags: ['Trashed web links'],
  summary: 'Restore web link',
  description:
    'Restores a web link that has been moved to the trash.\n\nAn optional new parent ID can be provided to restore the  web link to in case\nthe original folder has been deleted.',
  operationId: 'post_web_links_id',
  request: {
    params: z.object({
      web_link_id: z
        .string()
        .openapi({
          param: {
            name: 'web_link_id',
            in: 'path',
            description: 'The ID of the web link.',
            required: true,
            schema: { type: 'string' },
            example: '12345',
          },
        }),
    }),
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'fields',
            in: 'query',
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            required: false,
            schema: { type: 'array', items: { type: 'string' } },
            example: ['id', 'type', 'name'],
            explode: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'An optional new name for the web link.',
                  example: 'Restored.docx',
                }),
              parent: z
                .object({
                  id: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'The ID of parent item.', example: '123' }),
                })
                .openapi({ description: 'The parent for this item.', required: [] })
                .and(
                  z
                    .any()
                    .openapi({
                      description:
                        'Specifies an optional ID of a folder to restore the web link\nto when the original folder no longer exists.\n\nPlease be aware that this ID will only be used if the original\nfolder no longer exists. Use this ID to provide a fallback\nlocation to restore the web link to if the original location\nhas been deleted.',
                    }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns a web link object when it has been restored.',
      content: { 'application/json': { schema: TrashWebLinkRestoredSchema } },
    },
    403: {
      description:
        'Returns an error if the user does not have access to the folder\nthe web link is being restored to, or the user does not have permission\nto restore web link from the trash.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description: 'Returns an error if the web link is not in the trash.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    409: {
      description:
        'Returns an error if there is an web link with the same name\nin the folder the web link is being restored to.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

