export const putUsersUserIdFolders0Route = createRoute({
  method: 'put',
  path: '/users/{user_id}/folders/0',
  tags: ['Transfer folders'],
  summary: 'Transfer owned folders',
  description:
    "Move all of the items (files, folders and workflows) owned by a user into\nanother user's account.\n\nOnly the root folder (`0`) can be transferred.\n\nFolders can only be moved across users by users with administrative\npermissions.\n\nAll existing shared links and folder-level collaborations are transferred\nduring the operation. Please note that while collaborations at the individual\nfile-level are transferred during the operation, the collaborations are\ndeleted when the original user is deleted.\n\nIf the user has a large number of items across all folders, the call will\nbe run asynchronously. If the operation is not completed within 10 minutes,\nthe user will receive a 200 OK response, and the operation will continue running.\n\nIf the destination path has a metadata cascade policy attached to any of\nthe parent folders, a metadata cascade operation will be kicked off\nasynchronously.\n\nThere is currently no way to check for when this operation is finished.\n\nThe destination folder's name will be in the format `{User}'s Files and\nFolders`, where `{User}` is the display name of the user.\n\nTo make this API call your application will need to have the \"Read and write\nall files and folders stored in Box\" scope enabled.\n\nPlease make sure the destination user has access to `Relay` or `Relay Lite`,\nand has access to the files and folders involved in the workflows being\ntransferred.\n\nAdmins will receive an email when the operation is completed.",
  operationId: 'put_users_id_folders_0',
  request: {
    params: z.object({
      user_id: z
        .string()
        .openapi({
          param: {
            name: 'user_id',
            in: 'path',
            description: 'The ID of the user.',
            required: true,
            schema: { type: 'string' },
            example: '12345',
          },
        }),
    }),
    query: z.object({
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'fields',
            in: 'query',
            description:
              'A comma-separated list of attributes to include in the\nresponse. This can be used to request fields that are\nnot normally returned in a standard response.\n\nBe aware that specifying this parameter will have the\neffect that none of the standard fields are returned in\nthe response unless explicitly specified, instead only\nfields for the mini representation are returned, additional\nto the fields requested.',
            required: false,
            schema: { type: 'array', items: { type: 'string' } },
            example: ['id', 'type', 'name'],
            explode: false,
          },
        }),
      notify: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'notify',
            in: 'query',
            description:
              'Determines if users should receive email notification\nfor the action performed.',
            required: false,
            schema: { type: 'boolean' },
            example: true,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              owned_by: z
                .object({
                  id: z
                    .string()
                    .openapi({
                      description: 'The ID of the user who the folder will be\ntransferred to.',
                      example: '1232234',
                    }),
                })
                .openapi({
                  description: 'The user who the folder will be transferred to.',
                  required: ['id'],
                }),
            })
            .openapi({ required: ['owned_by'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Returns the information for the newly created\ndestination folder.',
      content: { 'application/json': { schema: FolderFullSchema } },
    },
    403: {
      description:
        'Returns an error when folder ownership cannot be\ntransferred to another user.\n\n* `forbidden_by_policy`: Returned if ownership transfer\n is forbidden due to information barrier restrictions.\n* `Cannot transfer files from/to higher privileged accounts`: You can only transfer content to or from managed users or your own account,\n not other co-admins or admins. Admins can transfer content between any users, including co-admins and managed users.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

