export const getUsersUserIdMembershipsRoute = createRoute({
  method: 'get',
  path: '/users/{user_id}/memberships',
  tags: ['Group memberships'],
  summary: "List user's groups",
  description:
    'Retrieves all the groups for a user. Only members of this\ngroup or users with admin-level permissions will be able to\nuse this API.',
  operationId: 'get_users_id_memberships',
  request: {
    params: z.object({
      user_id: z
        .string()
        .openapi({
          param: {
            name: 'user_id',
            in: 'path',
            description: 'The ID of the user.',
            required: true,
            schema: { type: 'string' },
            example: '12345',
          },
        }),
    }),
    query: z.object({
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'The maximum number of items to return per page.',
            required: false,
            schema: { type: 'integer', format: 'int64', maximum: 1000 },
            example: 1000,
          },
        }),
      offset: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description:
              'The offset of the item at which to begin the response.\n\nQueries with offset parameter value\nexceeding 10000 will be rejected\nwith a 400 response.',
            required: false,
            schema: { type: 'integer', format: 'int64', default: 0 },
            example: 1000,
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns a collection of membership objects. If there are no\nmemberships, an empty collection will be returned.',
      content: { 'application/json': { schema: GroupMembershipsSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

