export const postRetentionPoliciesRoute = createRoute({
  method: 'post',
  path: '/retention_policies',
  tags: ['Retention policies'],
  summary: 'Create retention policy',
  description: 'Creates a retention policy.',
  operationId: 'post_retention_policies',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              policy_name: z
                .string()
                .openapi({
                  description: 'The name for the retention policy.',
                  example: 'Some Policy Name',
                }),
              description: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'The additional text description of the retention policy.',
                  example: 'Policy to retain all reports for at least one month',
                }),
              policy_type: z
                .enum(['finite', 'indefinite'])
                .openapi({
                  description:
                    'The type of the retention policy. A retention\npolicy type can either be `finite`, where a\nspecific amount of time to retain the content is known\nupfront, or `indefinite`, where the amount of time\nto retain the content is still unknown.',
                  example: 'finite',
                }),
              disposition_action: z
                .enum(['permanently_delete', 'remove_retention'])
                .openapi({
                  description:
                    'The disposition action of the retention policy.\n`permanently_delete` deletes the content\nretained by the policy permanently.\n`remove_retention` lifts retention policy\nfrom the content, allowing it to be deleted\nby users once the retention policy has expired.',
                  example: 'permanently_delete',
                }),
              retention_length: z
                .xor([z.string().nullable(), z.number()])
                .exactOptional()
                .openapi({
                  description:
                    'The length of the retention policy. This value\nspecifies the duration in days that the retention\npolicy will be active for after being assigned to\ncontent.  If the policy has a `policy_type` of\n`indefinite`, the `retention_length` will also be\n`indefinite`.',
                  example: '365',
                }),
              retention_type: z
                .enum(['modifiable', 'non_modifiable'])
                .exactOptional()
                .openapi({
                  description:
                    'Specifies the retention type:\n\n* `modifiable`: You can modify the retention policy. For example,\nyou can add or remove folders, shorten or lengthen\nthe policy duration, or delete the assignment.\nUse this type if your retention policy\nis not related to any regulatory purposes.\n\n* `non_modifiable`: You can modify the retention policy\nonly in a limited way: add a folder, lengthen the duration,\nretire the policy, change the disposition action\nor notification settings. You cannot perform other actions,\nsuch as deleting the assignment or shortening the\npolicy duration. Use this type to ensure\ncompliance with regulatory retention policies.',
                  example: 'modifiable',
                }),
              can_owner_extend_retention: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether the owner of a file will be allowed to\nextend the retention.',
                  example: true,
                }),
              max_extension_length: RetentionPolicyMaxExtensionLengthRequestSchema.exactOptional(),
              are_owners_notified: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether owner and co-owners of a file are notified\nwhen the policy nears expiration.',
                  example: true,
                }),
              custom_notification_recipients: z
                .array(UserMiniSchema)
                .exactOptional()
                .openapi({
                  description:
                    'A list of users notified when\nthe retention policy duration is about to end.',
                }),
            })
            .openapi({ required: ['policy_name', 'policy_type', 'disposition_action'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns a new retention policy object.',
      content: { 'application/json': { schema: RetentionPolicySchema } },
    },
    400: {
      description:
        'Returns a `bad_request` error when the `retention_length` was\nspecified for an `indefinite` retention policy, an incorrect\n`disposition_action` was set, `max_extension_length` is not allowed for the\ngiven policy type or disposition action, or description exceeds maximum length of\n500 characters.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returns an error if the user does not have the required permissions\nto create a retention policy.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    409: {
      description: 'Returns an error if a retention policy with the given name already exists.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

