export const postLegalHoldPoliciesRoute = createRoute({
  method: 'post',
  path: '/legal_hold_policies',
  tags: ['Legal hold policies'],
  summary: 'Create legal hold policy',
  description: 'Create a new legal hold policy.',
  operationId: 'post_legal_hold_policies',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              policy_name: z
                .string()
                .max(254)
                .openapi({ description: 'The name of the policy.', example: 'Sales Policy' }),
              description: z
                .string()
                .max(500)
                .exactOptional()
                .openapi({
                  description: 'A description for the policy.',
                  example: 'A custom policy for the sales team',
                }),
              filter_started_at: z.iso
                .datetime({ offset: true })
                .max(500)
                .exactOptional()
                .openapi({
                  description:
                    'The filter start date.\n\nWhen this policy is applied using a `custodian` legal\nhold assignments, it will only apply to file versions\ncreated or uploaded inside of the\ndate range. Other assignment types, such as folders and\nfiles, will ignore the date filter.\n\nRequired if `is_ongoing` is set to `false`.',
                  example: '2012-12-12T10:53:43-08:00',
                }),
              filter_ended_at: z.iso
                .datetime({ offset: true })
                .max(500)
                .exactOptional()
                .openapi({
                  description:
                    'The filter end date.\n\nWhen this policy is applied using a `custodian` legal\nhold assignments, it will only apply to file versions\ncreated or uploaded inside of the\ndate range. Other assignment types, such as folders and\nfiles, will ignore the date filter.\n\nRequired if `is_ongoing` is set to `false`.',
                  example: '2012-12-18T10:53:43-08:00',
                }),
              is_ongoing: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether new assignments under this policy should\ncontinue applying to files even after initialization.\n\nWhen this policy is applied using a legal hold assignment,\nit will continue applying the policy to any new file versions\neven after it has been applied.\n\nFor example, if a legal hold assignment is placed on a user\ntoday, and that user uploads a file tomorrow, that file will\nget held. This will continue until the policy is retired.\n\nRequired if no filter dates are set.',
                  example: true,
                }),
            })
            .openapi({ required: ['policy_name'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Returns a new legal hold policy object.',
      content: { 'application/json': { schema: LegalHoldPolicySchema } },
    },
    400: {
      description:
        'Returns an error if required parameters are missing,\nor neither `is_ongoing` or filter dates are specified.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    409: {
      description: 'Returns an error if a policy with this name already exists.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

