export const getCollaborationWhitelistExemptTargetsRoute = createRoute({
  method: 'get',
  path: '/collaboration_whitelist_exempt_targets',
  tags: ['Domain restrictions (User exemptions)'],
  summary: 'List users exempt from collaboration domain restrictions',
  description:
    'Returns a list of users who have been exempt from the collaboration\ndomain restrictions.',
  operationId: 'get_collaboration_whitelist_exempt_targets',
  request: {
    query: z.object({
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'marker',
            in: 'query',
            description:
              'Defines the position marker at which to begin returning results. This is\nused when paginating using marker-based pagination.\n\nThis requires `usemarker` to be set to `true`.',
            required: false,
            schema: { type: 'string' },
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'The maximum number of items to return per page.',
            required: false,
            schema: { type: 'integer', format: 'int64', maximum: 1000 },
            example: 1000,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returns a collection of user exemptions.',
      content: { 'application/json': { schema: CollaborationAllowlistExemptTargetsSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

