export const postZipDownloadsRoute = createRoute({
  method: 'post',
  path: '/zip_downloads',
  tags: ['Zip Downloads'],
  summary: 'Create zip download',
  description:
    "Creates a request to download multiple files and folders as a single `zip`\narchive file. This API does not return the archive but instead performs all\nthe checks to ensure that the user has access to all the items, and then\nreturns a `download_url` and a `status_url` that can be used to download the\narchive.\n\nThe limit for an archive is either the Account's upload limit or\n10,000 files, whichever is met first.\n\n**Note**: Downloading a large file can be\naffected by various\nfactors such as distance, network latency,\nbandwidth, and congestion, as well as packet loss\nratio and current server load.\nFor these reasons we recommend that a maximum ZIP archive\ntotal size does not exceed 25GB.",
  operationId: 'post_zip_downloads',
  request: { body: { content: { 'application/json': { schema: ZipDownloadRequestSchema } } } },
  responses: {
    202: {
      description:
        'If the `zip` archive is ready to be downloaded, the API will return a\nresponse that will include a `download_url`, a `status_url`, as well as\nany conflicts that might have occurred when creating the request.',
      content: {
        'application/json': {
          schema: ZipDownloadSchema,
          examples: {
            default: {
              value: {
                download_url:
                  'https://dl.boxcloud.com/2.0/zip_downloads/29l00nfxDyHOt7RphI9zT_w==nDnZEDjY2S8iEWWCHEEiptFxwoWojjlibZjJ6geuE5xnXENDTPxzgbks_yY=/content',
                status_url:
                  'https://api.box.com/2.0/zip_downloads/29l00nfxDyHOt7RphI9zT_w==nDnZEDjY2S8iEWWCHEEiptFxwoWojjlibZjJ6geuE5xnXENDTPxzgbks_yY=/status',
                expires_at: '2020-07-22T11:26:08Z',
                name_conflicts: [
                  [
                    {
                      id: '12345',
                      type: 'file',
                      original_name: 'Report.pdf',
                      download_name: '3aa6a7.pdf',
                    },
                    {
                      id: '34325',
                      type: 'file',
                      original_name: 'Report.pdf',
                      download_name: '5d53f2.pdf',
                    },
                  ],
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description:
        'Returns an error if some of the parameters are missing or\nnot valid.\n\nIn most cases, this error might happen because the JSON request body is\nnot valid JSON, any of the items has an incorrect or missing ID, any of\nthe items is not a file or folder, or the root folder with ID `0` has been\nadded to the list of folders to add to the archive.\n\nThe following is a list of common error codes for this response.\n\n* `bad_request` - the request body is missing, invalid, or both the list\nof files and folders are empty. Additionally, it this error might be\nreturned when attempting to add the root folder with ID `0` to an archive.\n* `zip_download_file_count_exceeded_limit` - the requested files and\nfolders would result in an archive with more than 10,000 files. The\nrequest will have to be split into multiple requests to reduce the number\nof files per archive.\n* `zip_download_pre_compressed_bytes_exceeded_limit` - the requested files\nand folders would result in an archive with more than the allowed download\nlimit. The request will have to be split into multiple requests to reduce\nthe size of the archive.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    401: {
      description:
        'Returned when the access token provided in the `Authorization` header\nis not recognized or not provided.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returned when an authorization header is provided but the user does not\nhave access to the items.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

export const getZipDownloadsZipDownloadIdContentRoute = createRoute({
  method: 'get',
  path: '/zip_downloads/{zip_download_id}/content',
  tags: ['Zip Downloads'],
  summary: 'Download zip archive',
  description:
    "Returns the contents of a `zip` archive in binary format. This URL does not\nrequire any form of authentication and could be used in a user's browser to\ndownload the archive to a user's device.\n\nBy default, this URL is only valid for a few seconds from the creation of\nthe request for this archive. Once a download has started it can not be\nstopped and resumed, instead a new request for a zip archive would need to\nbe created.\n\nThe URL of this endpoint should not be considered as fixed. Instead, use\nthe [Create zip download](https://developer.box.com/reference/post-zip-downloads) API to request to create a\n`zip` archive, and then follow the `download_url` field in the response to\nthis endpoint.",
  operationId: 'get_zip_downloads_id_content',
  request: {
    params: z.object({
      zip_download_id: z
        .string()
        .openapi({
          param: {
            name: 'zip_download_id',
            in: 'path',
            description: 'The unique identifier that represent this `zip` archive.',
            required: true,
            schema: { type: 'string' },
            example:
              'Lu6fA9Ob-jyysp3AAvMF4AkLEwZwAYbL=tgj2zIC=eK9RvJnJbjJl9rNh2qBgHDpyOCAOhpM=vajg2mKq8Mdd',
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns the content of the items requested for this download, formatted as\na stream of files and folders in a `zip` archive.',
      content: {
        'application/octet-stream': {
          schema: z
            .file()
            .openapi({
              type: 'string',
              format: 'binary',
              description:
                'The binary content of the archive, which will include the items\nrequested for this download.',
            }),
        },
      },
      headers: z.object({
        'Content-Disposition': {
          description: 'The name of the archive to be downloaded.',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'The name of the archive to be downloaded.',
              param: { required: false },
              example: 'attachment;filename="Avatars.zip";filename*=UTF-8\'\'Avatars.zip',
            }),
        },
      }),
    },
    404: {
      description:
        'Returns an error if the ID of this download request is not valid. This\nerror can also be returned if this URL has been called before. To\nre-download this archive, please create a new request for a zip download.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    429: {
      description:
        'Returns an error if the number of concurrent zip downloads has been\nreached for either the user or the enterprise.\n\n* `user_too_many_concurrent_downloads` - the maximum of 5 parallel\ndownloads of zip archives per user has been met.\n* `enterprise_too_many_concurrent_downloads` - the maximum of 10 parallel\ndownloads of zip archives per enterprise has been met.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
  security: [],
  servers: [
    {
      url: 'https://dl.boxcloud.com/2.0',
      description:
        'An opaque server URL for downloading zip downloads. The format\nof this URL might change over time.',
    },
  ],
})

