export const getSignRequestsRoute = createRoute({
  method: 'get',
  path: '/sign_requests',
  tags: ['Box Sign requests'],
  summary: 'List Box Sign requests',
  description:
    'Gets signature requests created by a user. If the `sign_files` and/or\n`parent_folder` are deleted, the signature request will not return in the list.',
  operationId: 'get_sign_requests',
  request: {
    query: z.object({
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'marker',
            in: 'query',
            description:
              'Defines the position marker at which to begin returning results. This is\nused when paginating using marker-based pagination.\n\nThis requires `usemarker` to be set to `true`.',
            required: false,
            schema: { type: 'string' },
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'The maximum number of items to return per page.',
            required: false,
            schema: { type: 'integer', format: 'int64', maximum: 1000 },
            example: 1000,
          },
        }),
      senders: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'senders',
            in: 'query',
            description:
              'A list of sender emails to filter the signature requests by sender.\nIf provided, `shared_requests` must be set to `true`.',
            required: false,
            schema: { type: 'array', items: { type: 'string' } },
            example: ['sender1@boxdemo.com', 'sender2@boxdemo.com'],
          },
        }),
      shared_requests: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'shared_requests',
            in: 'query',
            description:
              'If set to `true`, only includes requests that user is not an owner,\nbut user is a collaborator. Collaborator access is determined by the\nuser access level of the sign files of the request.\nDefault is `false`. Must be set to `true` if `senders` are provided.',
            required: false,
            schema: { type: 'boolean', default: false },
            example: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returns a collection of sign requests.',
      content: { 'application/json': { schema: SignRequestsSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

