export const postWorkflowsWorkflowIdStartRoute = createRoute({
  method: 'post',
  path: '/workflows/{workflow_id}/start',
  tags: ['Workflows'],
  summary: 'Starts workflow based on request body',
  description:
    'Initiates a flow with a trigger type of `WORKFLOW_MANUAL_START`.\n\nYou application must be authorized to use the `Manage Box Relay` application\nscope within the developer console.',
  operationId: 'post_workflows_id_start',
  request: {
    params: z.object({
      workflow_id: z
        .string()
        .openapi({
          param: {
            name: 'workflow_id',
            in: 'path',
            description: 'The ID of the workflow.',
            required: true,
            schema: { type: 'string' },
            example: '12345',
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              type: z
                .literal('workflow_parameters')
                .exactOptional()
                .openapi({
                  description: 'The type of the parameters object.',
                  example: 'workflow_parameters',
                }),
              flow: z
                .object({
                  type: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'The type of the flow object.', example: 'flow' }),
                  id: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'The id of the flow.', example: '123456789' }),
                })
                .openapi({ description: 'The flow that will be triggered.', required: [] }),
              files: z
                .array(
                  z
                    .object({
                      type: z
                        .literal('file')
                        .exactOptional()
                        .openapi({ description: 'The type of the file object.', example: 'file' }),
                      id: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'The id of the file.', example: '12345678' }),
                    })
                    .openapi({
                      description: 'A file the workflow should start for.',
                      required: [],
                    }),
                )
                .openapi({
                  description:
                    "The array of files for which the workflow should start. All files\nmust be in the workflow's configured folder.",
                }),
              folder: z
                .object({
                  type: z
                    .literal('folder')
                    .exactOptional()
                    .openapi({ description: 'The type of the folder object.', example: 'folder' }),
                  id: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'The id of the folder.', example: '87654321' }),
                })
                .openapi({
                  description: 'The folder object for which the workflow is configured.',
                  required: [],
                }),
              outcomes: z
                .array(OutcomeSchema)
                .exactOptional()
                .openapi({ description: 'A configurable outcome the workflow should complete.' }),
            })
            .openapi({ required: ['flow', 'files', 'folder'] }),
        },
      },
    },
  },
  responses: {
    204: { description: 'Starts the workflow.' },
    400: {
      description:
        'Returns an error if some of the parameters are missing or\nnot valid.\n\n* `workflow_is_not_enabled` when the workflow is not enabled.\n* `workflow_not_active_on_provided_folder` when the workflow is not\n  enabled for the specified folder id.\n* `parameters_provided_do_not_match_target_outcome` when the provided\n  parameters do not match the expected parameters.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        'Returns an error if there are insufficient permissions.\n\n* `insufficient_access` when the user does not have access rights to file\n  or folder.\n* `missing_relay_full_access` when the user does not have access to Relay\n  Full.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    404: {
      description:
        'Returns an error if the workflow could not be found,\nor the authenticated user does not have access to the workflow.\n\n* `workflow_not_found` when the workflow is not found.\n* `flow_missing_or_inaccessible` when the flow is not a manual start flow.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

