export const getAiAgentsRoute = createRoute({
  method: 'get',
  path: '/ai_agents',
  tags: ['AI Studio'],
  summary: 'List AI agents',
  description: 'Lists AI agents based on the provided parameters.',
  operationId: 'get_ai_agents',
  request: {
    query: z.object({
      mode: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'mode',
            in: 'query',
            description:
              'The mode to filter the agent config to return. Possible values are: `ask`, `text_gen`, and `extract`.',
            required: false,
            schema: { type: 'array', items: { type: 'string' } },
            example: ['ask', 'text_gen', 'extract'],
            explode: false,
          },
        }),
      fields: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'fields',
            in: 'query',
            description: 'The fields to return in the response.',
            required: false,
            schema: { type: 'array', items: { type: 'string' } },
            example: ['ask', 'text_gen', 'extract'],
            explode: false,
          },
        }),
      agent_state: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'agent_state',
            in: 'query',
            description:
              'The state of the agents to return. Possible values are: `enabled`, `disabled` and `enabled_for_selected_users`.',
            required: false,
            schema: { type: 'array', items: { type: 'string' } },
            example: ['enabled'],
            explode: false,
          },
        }),
      include_box_default: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_box_default',
            in: 'query',
            description: 'Whether to include the Box default agents in the response.',
            required: false,
            schema: { type: 'boolean', default: false },
            example: true,
          },
        }),
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'marker',
            in: 'query',
            description: 'Defines the position marker at which to begin returning results.',
            required: false,
            schema: { type: 'string' },
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'The maximum number of items to return per page.',
            required: false,
            schema: { type: 'integer', format: 'int64', maximum: 1000 },
            example: 1000,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'A successful response including the agents list.',
      content: { 'application/json': { schema: AiMultipleAgentResponseSchema } },
    },
    400: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    500: {
      description: 'An unexpected server error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

