export const postMetadataTaxonomiesRoute = createRoute({
  method: 'post',
  path: '/metadata_taxonomies',
  tags: ['Metadata taxonomies'],
  summary: 'Create metadata taxonomy',
  description: 'Creates a new metadata taxonomy that can be used in\nmetadata templates.',
  operationId: 'post_metadata_taxonomies',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              key: z
                .string()
                .max(256)
                .exactOptional()
                .openapi({
                  description:
                    'The taxonomy key. If it is not provided in the request body, it will be \ngenerated from the `displayName`. The `displayName` would be converted \nto lower case, and all spaces and non-alphanumeric characters replaced \nwith underscores.',
                  example: 'geography',
                }),
              displayName: z
                .string()
                .max(4096)
                .openapi({
                  description: 'The display name of the taxonomy.',
                  example: 'Geography',
                }),
              namespace: z
                .string()
                .max(4096)
                .openapi({
                  description: 'The namespace of the metadata taxonomy to create.',
                  example: 'enterprise_123456',
                }),
            })
            .openapi({ required: ['displayName', 'namespace'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'The schema representing the metadata taxonomy created.',
      content: { 'application/json': { schema: MetadataTaxonomySchema } },
    },
    400: {
      description:
        'Returned if the request parameters or body is not valid.\n\n* `bad_request` when the body does not contain a valid request. In many\ncases this response will include extra details on what fields are missing.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    403: {
      description:
        "Returned when the user does not have the permission to create the metadata\ntaxonomy. This can happen for a few reasons, most commonly when the user\ndoes not have (co-)admin permissions, or the user doesn't have access to \nthe provided namespace.",
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

export const getMetadataTaxonomiesNamespaceRoute = createRoute({
  method: 'get',
  path: '/metadata_taxonomies/{namespace}',
  tags: ['Metadata taxonomies'],
  summary: 'Get metadata taxonomies for namespace',
  description: 'Used to retrieve all metadata taxonomies in a namespace.',
  operationId: 'get_metadata_taxonomies_id',
  request: {
    params: z.object({
      namespace: z
        .string()
        .openapi({
          param: {
            name: 'namespace',
            in: 'path',
            description: 'The namespace of the metadata taxonomy.',
            required: true,
            schema: { type: 'string' },
            example: 'enterprise_123456',
          },
        }),
    }),
    query: z.object({
      marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'marker',
            in: 'query',
            description:
              'Defines the position marker at which to begin returning results. This is\nused when paginating using marker-based pagination.\n\nThis requires `usemarker` to be set to `true`.',
            required: false,
            schema: { type: 'string' },
            example: 'JV9IRGZmieiBasejOG9yDCRNgd2ymoZIbjsxbJMjIs3kioVii',
          },
        }),
      limit: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64().max(1000n))
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'The maximum number of items to return per page.',
            required: false,
            schema: { type: 'integer', format: 'int64', maximum: 1000 },
            example: 1000,
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returns all of the metadata taxonomies within a namespace\nand their corresponding schema.',
      content: { 'application/json': { schema: MetadataTaxonomiesSchema } },
    },
    400: {
      description: 'Returned when the request parameters are not valid.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
    default: {
      description: 'An unexpected client error.',
      content: { 'application/json': { schema: ClientErrorSchema } },
    },
  },
})

